/**
 * The skins catalogue inside docs/ux-directions.html (tab "D"): one card per skin with a light and a dark mini-page built
 * from the same tokens the real site gets, so what you see is what the picker applies. Generated by `npm run skins`; a test
 * fails if the committed file is out of date.
 */
import { buildTokens, type SkinSpec, type Tokens } from './skins';

export const CATALOG_START = '<!-- SKINS:START (generated by npm run skins, do not edit) -->';
export const CATALOG_END = '<!-- SKINS:END -->';

const esc = (s: string): string => s.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');

function vars(spec: SkinSpec, t: Tokens): string {
  const font = esc(spec.sans ?? "ui-sans-serif, system-ui, 'Segoe UI', Roboto, Arial, sans-serif");
  const disp = esc(spec.display ?? spec.sans ?? "ui-sans-serif, system-ui, 'Segoe UI', Roboto, Arial, sans-serif");
  return [
    `--bg:${t.bg}`,
    `--card:${t.card}`,
    `--fg:${t.fg}`,
    `--mut:${t.muted}`,
    `--bd:${t.border}`,
    `--bds:${t.borderStrong}`,
    `--ac:${t.accent}`,
    `--acf:${t.accentFg}`,
    `--acs:${t.accentSoft}`,
    `--h1:${t.heroFrom}`,
    `--h2:${t.heroTo}`,
    `--r1:${spec.radius[0]}px`,
    `--r2:${spec.radius[1]}px`,
    `--r3:${spec.radius[2]}px`,
    `--sh:${esc(t.shadowMd)}`,
    `--font:${font}`,
    `--disp:${disp}`,
  ].join(';');
}

function mini(spec: SkinSpec, theme: 'light' | 'dark'): string {
  const t = buildTokens(spec, theme);
  return `<div class="mini" role="img" aria-label="${esc(spec.name)} ${theme} preview" style="${vars(spec, t)}">
        <div class="mh"><span class="ml">O</span><b>Opus Calculator</b><span class="mc">${theme}</span></div>
        <div class="mt">BMI calculator</div>
        <div class="mp">Your body mass index and WHO category.</div>
        <div class="mrow"><span class="mi">70 <em>kg</em></span><span class="mb">Share result</span><span class="mchip">Cite</span></div>
        <div class="mr"><small>Your BMI</small><strong>22.9</strong><span>Healthy weight</span></div>
      </div>`;
}

function fontKind(spec: SkinSpec): string {
  const f = (spec.sans ?? '').toLowerCase();
  if (f.includes('monospace')) return 'Monospace';
  if (f.includes('serif') && !f.includes('sans-serif')) return 'Serif';
  if (f.includes('rounded')) return 'Rounded sans';
  if (f.includes('helvetica')) return 'Grotesque sans';
  if (f.includes('avenir') || f.includes('century')) return 'Geometric sans';
  if (f.includes('seravek') || f.includes('candara')) return 'Humanist sans';
  return spec.display && spec.display.toLowerCase().includes('serif') ? 'Sans with serif headings' : 'System sans';
}

export function skinCatalogHtml(specs: readonly SkinSpec[]): string {
  const cards = specs.map((s) => {
    const shadow = { soft: 'soft shadow', flat: 'flat, no shadow', hard: 'hard offset shadow', glow: 'glow' }[s.shadow];
    const meta = [
      fontKind(s),
      `corners ${s.radius.join('/')} px`,
      shadow,
      s.spacing && s.spacing < 0.25 ? 'tight spacing' : s.spacing && s.spacing > 0.25 ? 'airy spacing' : 'regular spacing',
      s.layout ? `suggests the ${s.layout} layout` : '',
      s.aaa ? 'AAA contrast' : '',
    ]
      .filter(Boolean)
      .join(' · ');
    return `    <article class="sk" id="skin-${s.id}">
      <h3>${esc(s.name)}</h3>
      <p class="mood">${esc(s.mood)}</p>
      <div class="pair">
      ${mini(s, 'light')}
      ${mini(s, 'dark')}
      </div>
      <p class="meta">${esc(meta)}</p>
    </article>`;
  });
  return [CATALOG_START, '<div class="skins">', ...cards, '</div>', CATALOG_END].join('\n');
}

/** Replaces the generated block in the HTML file's text. */
export function withCatalog(html: string, specs: readonly SkinSpec[]): string {
  const a = html.indexOf(CATALOG_START);
  const b = html.indexOf(CATALOG_END);
  if (a < 0 || b < 0) throw new Error('docs/ux-directions.html has no SKINS:START / SKINS:END markers');
  return html.slice(0, a) + skinCatalogHtml(specs) + html.slice(b + CATALOG_END.length);
}
